<script setup lang="ts">interface Props{modelValue:string;label?:string;rows?:number}withDefaults(defineProps<Props>(),{rows:4});defineEmits<{(e:'update:modelValue',v:string):void}>()</script><template><label class="block space-y-1"><span v-if="label" class="text-sm">{{label}}</span><textarea :value="modelValue" :rows="rows" class="w-full rounded border border-slate-300 px-3 py-2" @input="$emit('update:modelValue', ($event.target as HTMLTextAreaElement).value)"/></label></template>
